```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("sprzedaz.txt");
    map<string, int> przychod;
    string region, produkt;
    int kwota;
    int total = 0;
    while (plik >> region >> produkt >> kwota) {
        przychod[region] += kwota;
        total += kwota;
    }

    cout << "a) Przychod wg regionu:" << endl;
    for (auto &p : przychod) {
        cout << "   " << p.first << ": " << p.second << endl;
    }

    cout << fixed << setprecision(2);
    cout << endl << "b) Udzialy procentowe:" << endl;
    for (auto &p : przychod) {
        cout << "   " << p.first << ": " << p.second * 100.0 / total << "%" << endl;
    }

    vector<pair<int, string>> ranking;
    for (auto &p : przychod) {
        ranking.push_back({p.second, p.first});
    }
    sort(ranking.begin(), ranking.end(), [](auto &a, auto &b) {
        return a.first > b.first;
    });

    cout << endl << "c) Ranking regionow:" << endl;
    for (int i = 0; i < (int)ranking.size(); i++) {
        cout << "   " << i + 1 << ". " << left << setw(10) << ranking[i].second
             << right << setw(5) << ranking[i].first << "  "
             << ranking[i].first * 100.0 / total << "%" << endl;
    }

    cout << endl << "d) Lider rynku: " << ranking[0].second
         << " (" << ranking[0].first * 100.0 / total << "%)" << endl;
    return 0;
}
```

Weryfikacja:
- Polnoc: 1200+800+500 = 2500
- Poludnie: 900+1100 = 2000
- Wschod: 600+400+300 = 1300
- Zachod: 1500+700 = 2200
- Total: 2500+2000+1300+2200 = 8000

a) map iteruje alfa: Polnoc(2500), Poludnie(2000), Wschod(1300), Zachod(2200)

b) Udzialy:
- Polnoc: 2500*100/8000 = 31.25%
- Poludnie: 2000*100/8000 = 25.00%
- Wschod: 1300*100/8000 = 16.25%
- Zachod: 2200*100/8000 = 27.50%

c) Malejaco: Polnoc(2500, 31.25%), Zachod(2200, 27.50%), Poludnie(2000, 25.00%), Wschod(1300, 16.25%)

d) Lider: Polnoc (31.25%)
